fn is_prime(n: i8) -> bool {
    // Numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisors from 2 up to sqrt(n) (optimization)
    // For i8, we can just check up to n/2 since sqrt(127) ≈ 11.3
    let limit = (n as f32).sqrt() as i8 + 1;
    
    for i in 2..=limit {
        if n % i == 0 {
            return false;
        }
    }
    
    true
}